"""Database tables.

Every table carries user_id (single user today, multi-user door kept open) and created_at / updated_at.
Rows that change carry a version column for optimistic locking.
"""

from __future__ import annotations

from sqlalchemy import (
    BigInteger,
    Boolean,
    Column,
    DateTime,
    ForeignKey,
    Identity,
    Index,
    Integer,
    MetaData,
    Numeric,
    Table,
    Text,
    UniqueConstraint,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import JSONB

# Fixed constraint names, so autogenerated migrations stay stable.
metadata = MetaData(
    naming_convention={
        "ix": "ix_%(table_name)s_%(column_0_N_name)s",
        "uq": "uq_%(table_name)s_%(column_0_N_name)s",
        "pk": "pk_%(table_name)s",
        "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    }
)

USER_ID = 1  # the single user


def _user() -> Column:
    """Return the ``user_id`` column every table carries."""
    return Column("user_id", Integer, nullable=False, server_default=text(str(USER_ID)))


def _created() -> Column:
    """Return a ``created_at`` column set by the database."""
    return Column("created_at", DateTime(timezone=True), nullable=False, server_default=func.now())


def _updated() -> Column:
    """Return an ``updated_at`` column (writers refresh it on update)."""
    return Column("updated_at", DateTime(timezone=True), nullable=False, server_default=func.now())


def _id() -> Column:
    """Return a bigint identity primary key column."""
    return Column("id", BigInteger, Identity(), primary_key=True)


# Every inbound event (Telegram update, tap, dashboard action, timer). Doubles as the audit log.
events = Table(
    "events",
    metadata,
    _id(),
    _user(),
    Column("type", Text, nullable=False),
    Column("payload", JSONB, nullable=False),
    Column("idempotency_key", Text, nullable=False, unique=True),
    Column("telegram_update_id", BigInteger, unique=True),
    _created(),
)

# Postgres work queue (claimed with FOR UPDATE SKIP LOCKED). The design's `queue` table is the
# ranked *jobs* queue; this one holds units of work for the worker process.
work_items = Table(
    "work_items",
    metadata,
    _id(),
    _user(),
    Column("kind", Text, nullable=False),
    Column("payload", JSONB, nullable=False),
    Column("idempotency_key", Text, unique=True),
    Column("status", Text, nullable=False, server_default="queued"),  # queued|running|done|failed
    Column("attempts", Integer, nullable=False, server_default="0"),
    Column("run_after", DateTime(timezone=True), nullable=False, server_default=func.now()),
    Column("locked_by", Text),
    Column("locked_until", DateTime(timezone=True)),
    Column("last_error", Text),
    Column("finished_at", DateTime(timezone=True)),
    _created(),
    _updated(),
    Index("ix_work_items_claim", "status", "run_after"),
)

# Next sequence number per outbox partition (one row per card / channel).
outbox_partitions = Table(
    "outbox_partitions",
    metadata,
    Column("partition_key", Text, primary_key=True),
    Column("last_seq", BigInteger, nullable=False),
)

# Every outgoing effect, written in the same transaction as the state change that causes it.
outbox = Table(
    "outbox",
    metadata,
    _id(),
    _user(),
    Column("partition_key", Text, nullable=False),
    Column("seq", BigInteger, nullable=False),
    Column("kind", Text, nullable=False),  # telegram | gmail
    Column("payload", JSONB, nullable=False),  # never holds tokens
    Column("idempotency_key", Text, nullable=False, unique=True),
    Column("status", Text, nullable=False, server_default="pending"),  # pending|delivered|dead|skipped
    Column("attempts", Integer, nullable=False, server_default="0"),
    Column("external_id", Text),  # Telegram message id / Gmail message id
    Column("next_attempt_at", DateTime(timezone=True), nullable=False, server_default=func.now()),
    Column("last_error", Text),
    Column("delivered_at", DateTime(timezone=True)),
    _created(),
    _updated(),
    UniqueConstraint("partition_key", "seq"),
    Index("ix_outbox_external_id", "external_id"),
    Index(
        "ix_outbox_undelivered",
        "partition_key",
        "seq",
        postgresql_where=text("status IN ('pending', 'dead')"),
    ),
)

# Durable approvals. Send tokens are minted from these at delivery time and never stored.
approvals = Table(
    "approvals",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False),
    Column("kind", Text, nullable=False),  # resume | email
    Column("target_id", BigInteger, nullable=False),
    Column("target_version", Integer, nullable=False),
    Column("approved_at", DateTime(timezone=True), nullable=False),
    Column("consumed_at", DateTime(timezone=True)),
    Column("version", Integer, nullable=False, server_default="1"),
    _created(),
    _updated(),
)

# One row per /start run; the lease, counters and cost live here.
runs = Table(
    "runs",
    metadata,
    _id(),
    _user(),
    Column("status", Text, nullable=False),  # running|draining|finished|failed
    Column("lease_holder", Text),
    Column("heartbeat_at", DateTime(timezone=True)),
    Column("started_at", DateTime(timezone=True), nullable=False),
    Column("stopped_at", DateTime(timezone=True)),
    Column("stop_reason", Text),
    Column("stop_requested", Boolean, nullable=False, server_default=text("false")),
    Column("pause_requested", Boolean, nullable=False, server_default=text("false")),
    Column("card_cap", Integer, nullable=False),
    Column("current_step", Text),
    Column("counts", JSONB, nullable=False, server_default=text("'{}'::jsonb")),
    Column("tokens_in", BigInteger, nullable=False, server_default="0"),
    Column("tokens_out", BigInteger, nullable=False, server_default="0"),
    Column("cost_usd", Numeric(12, 6), nullable=False, server_default="0"),
    Column("trace_id", Text),
    Column("version", Integer, nullable=False, server_default="1"),
    _created(),
    _updated(),
    # The run lease: at most one running or draining run per user.
    Index(
        "uq_runs_one_active",
        "user_id",
        unique=True,
        postgresql_where=text("status IN ('running', 'draining')"),
    ),
)

# Where each job source left off (seen ids, last time, offsets).
source_cursors = Table(
    "source_cursors",
    metadata,
    _id(),
    _user(),
    Column("source", Text, nullable=False),
    Column("cursor", JSONB, nullable=False),
    Column("version", Integer, nullable=False, server_default="1"),
    _created(),
    _updated(),
    UniqueConstraint("user_id", "source"),
)

# Global switches: kill switch, dispatcher paused (restore procedure).
system_flags = Table(
    "system_flags",
    metadata,
    Column("key", Text, primary_key=True),
    _user(),
    Column("value", JSONB, nullable=False),
    Column("version", Integer, nullable=False, server_default="1"),
    _updated(),
)

# One row per LLM call: drives budgets, run cost and the 1.5x alert.
llm_usage = Table(
    "llm_usage",
    metadata,
    _id(),
    _user(),
    Column("run_id", BigInteger, ForeignKey("runs.id")),
    Column("task", Text, nullable=False),
    Column("model", Text, nullable=False),
    Column("prompt_version", Text, nullable=False),
    Column("input_tokens", Integer, nullable=False),
    Column("output_tokens", Integer, nullable=False),
    Column("cache_read_tokens", Integer, nullable=False, server_default="0"),
    Column("cache_write_tokens", Integer, nullable=False, server_default="0"),
    Column("cost_usd", Numeric(12, 6), nullable=False),
    Column("valid_output", Boolean, nullable=False),
    _created(),
    Index("ix_llm_usage_created_at", "created_at"),
)

# ---- Profile, structured resume, preferences ---------------------------------------------

# The user's facts, one per row, with evidence. Only confirmed
# items are used for scoring, tailoring and emails.
profile_items = Table(
    "profile_items",
    metadata,
    _id(),
    _user(),
    Column("kind", Text, nullable=False),
    Column("text", Text, nullable=False),
    Column("evidence", Text, nullable=False),
    Column("source", Text, nullable=False),  # resume | notes | chat
    Column("status", Text, nullable=False, server_default="draft"),  # draft | confirmed | rejected
    Column("attrs", JSONB, nullable=False, server_default=text("'{}'::jsonb")),
    Column("import_key", Text),  # stable key from the resume importer, e.g. "skill:python"
    Column("confirmed_at", DateTime(timezone=True)),
    Column("version", Integer, nullable=False, server_default="1"),
    _created(),
    _updated(),
    Index("ix_profile_items_status", "status"),
)

# The structured resume. One row per base resume version; tailored copies live in resume_versions.
resume_doc = Table(
    "resume_doc",
    metadata,
    _id(),
    _user(),
    Column("doc", JSONB, nullable=False),  # domain.resume_doc.ResumeDoc
    Column("template_id", Text, nullable=False),
    Column("is_current", Boolean, nullable=False, server_default=text("true")),
    Column("source_file", Text),
    Column("pdf_key", Text),  # object-store key of the last render
    Column("parse_ok", Boolean),
    Column("render_report", JSONB),
    Column("version", Integer, nullable=False, server_default="1"),
    _created(),
    _updated(),
    Index("uq_resume_doc_current", "user_id", unique=True, postgresql_where=text("is_current")),
)

# One versioned preferences document per user.
preferences = Table(
    "preferences",
    metadata,
    Column("user_id", Integer, primary_key=True, server_default=text(str(USER_ID))),
    Column("data", JSONB, nullable=False),  # domain.preferences.Preferences
    Column("version", Integer, nullable=False, server_default="1"),
    _created(),
    _updated(),
)

# ---- Jobs, sightings, requirements, scores, queue, shared jobs ---------------------------

# One row per distinct job after dedup; sightings point to it.
jobs = Table(
    "jobs",
    metadata,
    _id(),
    _user(),
    Column(
        "canonical_key", Text, nullable=False, unique=True
    ),  # "linkedin:123" or "co:<company>|<title>|<city>"
    Column("board", Text),  # linkedin | naukri | indeed | ... (where the board job id came from)
    Column("board_job_id", Text),
    Column("company", Text, nullable=False),
    Column("company_norm", Text, nullable=False),
    Column("title", Text, nullable=False),
    Column("title_norm", Text, nullable=False),
    Column("city", Text),
    Column("location_raw", Text),
    Column("remote", Boolean, nullable=False, server_default=text("false")),
    Column("apply_url", Text, nullable=False),
    Column("jd_text", Text, nullable=False, server_default=""),
    Column("jd_is_snippet", Boolean, nullable=False, server_default=text("true")),
    Column("jd_hash", Text),
    Column("jd_simhash", BigInteger),
    # Full-JD lookup for snippet jobs: "found:<where>" (e.g. found:lever:acme, found:job_finder:<url>) or
    # "not_found"; NULL when the source gave the full JD or no lookup ran yet.
    Column("jd_lookup", Text),
    Column("experience_text", Text),
    # salary_*: no longer read or written (salary checks removed 2026-10-06); kept to avoid a migration.
    Column("salary_text", Text),
    Column("salary_low_lpa", Numeric(8, 2)),
    Column("salary_high_lpa", Numeric(8, 2)),
    Column("salary_conf", Text),  # stated | high | medium | low | unknown
    Column("salary_source", Text),  # jd | api_listing | api_estimate
    Column("posted_at", DateTime(timezone=True)),
    Column("first_seen_at", DateTime(timezone=True), nullable=False, server_default=func.now()),
    # pipeline: see domain.job.PipelineStatus (new -> filtered | screened_out | ... | queued | carded)
    Column("pipeline_status", Text, nullable=False, server_default="new"),
    Column("filter_reason", Text),
    Column("stage_a", Numeric(6, 4)),
    Column("locked_by", Text),
    Column("locked_until", DateTime(timezone=True)),
    Column("version", Integer, nullable=False, server_default="1"),
    _created(),
    _updated(),
    Index("ix_jobs_company_norm", "company_norm"),
    Index("ix_jobs_pipeline_status", "pipeline_status"),
)

# Every sighting of a job by a source (a repeat is a new sighting,
# never a second job).
job_sources = Table(
    "job_sources",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False),
    Column("source", Text, nullable=False),  # alert | api | search | shared
    Column("external_id", Text, nullable=False),  # message id + position, API id, URL...
    Column("url", Text),
    Column("posted_at", DateTime(timezone=True)),
    Column("seen_at", DateTime(timezone=True), nullable=False, server_default=func.now()),
    Column("run_id", BigInteger),
    Column("snippet", JSONB, nullable=False, server_default=text("'{}'::jsonb")),
    UniqueConstraint("source", "external_id"),
    Index("ix_job_sources_job_id", "job_id"),
)

# The LLM extraction cache: same JD + prompt + model -> same row.
requirements = Table(
    "requirements",
    metadata,
    _id(),
    _user(),
    Column("jd_hash", Text, nullable=False),
    Column("data", JSONB, nullable=False),  # domain.requirements.Requirements
    Column("prompt_version", Text, nullable=False),
    Column("model_id", Text, nullable=False),
    _created(),
    UniqueConstraint("jd_hash", "prompt_version", "model_id"),
)

# One row per scoring of a job; the newest row is current.
scores = Table(
    "scores",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False),
    Column("requirements_id", BigInteger, ForeignKey("requirements.id"), nullable=False),
    Column("stage_a", Numeric(6, 4)),
    Column("score", Numeric(6, 2), nullable=False),
    Column("parts", JSONB, nullable=False),
    Column("matched", JSONB, nullable=False),
    Column("gap", JSONB, nullable=False),
    Column("fit", JSONB),  # models.score.Fit: why you fit / what's missing (rubric 3+)
    Column("rubric_version", Integer, nullable=False),
    Column("profile_hash", Text, nullable=False),
    _created(),
    Index("ix_scores_job_id", "job_id"),
)

# The ranked jobs queue: raw score + time queued; age decay is computed when reading; 10-day expiry.
queue = Table(
    "queue",
    metadata,
    Column("job_id", BigInteger, ForeignKey("jobs.id"), primary_key=True, autoincrement=False),
    _user(),
    Column("score", Numeric(6, 2), nullable=False),
    Column("queued_at", DateTime(timezone=True), nullable=False),
    Column("expires_at", DateTime(timezone=True), nullable=False),
    Column("served_at", DateTime(timezone=True)),
)

# Jobs the user shared to the bot: a hit if JobPilot had already found the job, a miss if not (recall).
shared_jobs = Table(
    "shared_jobs",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False),
    Column("event_id", BigInteger, ForeignKey("events.id"), nullable=False, unique=True),
    Column("url", Text, nullable=False),
    Column("hit", Boolean, nullable=False),
    _created(),
)

# ---- Actionable cards and tailored resume versions --------------------------------------

# One card per job: its state machine row (status + version).
cards = Table(
    "cards",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False, unique=True),
    Column("status", Text, nullable=False, server_default="new"),
    Column("callback_token", Text, nullable=False, unique=True),
    Column("approved_resume_version_id", BigInteger, ForeignKey("resume_versions.id")),
    Column("telegram_outbox_id", BigInteger),
    Column("telegram_message_id", BigInteger),
    Column("applied_at", DateTime(timezone=True)),
    Column("outcome", Text),  # replied | interview | rejected | offer
    Column("outcome_at", DateTime(timezone=True)),
    Column("snoozed_until", DateTime(timezone=True)),
    Column("reminded_at", DateTime(timezone=True)),
    Column("version", Integer, nullable=False, server_default="1"),
    _created(),
    _updated(),
    Index("ix_cards_status", "status"),
)

# Immutable tailored resume versions; approvals name one exactly.
resume_versions = Table(
    "resume_versions",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False),
    Column("base_resume_id", BigInteger, ForeignKey("resume_doc.id"), nullable=False),
    Column("version", Integer, nullable=False),
    Column("doc", JSONB, nullable=False),
    Column("operations", JSONB, nullable=False, server_default=text("'[]'::jsonb")),
    Column("pdf_key", Text, nullable=False),
    Column("parse_ok", Boolean, nullable=False),
    Column("parse_report", JSONB, nullable=False),
    Column("keyword_coverage", JSONB, nullable=False),
    Column("diff", JSONB, nullable=False),
    Column("created_by", Text, nullable=False),
    Column("prompt_version", Text),  # the prompt + pinned model that produced the operations
    Column("model_id", Text),
    # Resume v2 (decision 31): this job's own copy of the base .tex, edited by the editor agent; the PDF is
    # built from it. `doc` then stays the base resume. `rounds` keeps every edit round (its .tex, review
    # score and verifier result) so each step can be compared or restored.
    Column("tex", Text),
    Column("rounds", JSONB),
    _created(),
    UniqueConstraint("job_id", "version"),
    Index("ix_resume_versions_job_id", "job_id"),
)

# ---- Guarded outreach --------------------------------------------------------------------
emails = Table(
    "emails",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False),
    Column("resume_version_id", BigInteger, ForeignKey("resume_versions.id"), nullable=False),
    Column("version", Integer, nullable=False),  # the draft number shown to the user (v1, v2, ...)
    Column("to_address", Text, nullable=False),
    Column("to_source", Text, nullable=False),
    Column("subject", Text, nullable=False),
    Column("body", Text, nullable=False),
    Column("citations", JSONB, nullable=False),
    Column("gmail_draft_id", Text),
    Column("gmail_thread_id", Text),  # the draft's thread: a send is found there, labelled SENT
    Column("status", Text, nullable=False, server_default="draft"),
    Column("lock_version", Integer, nullable=False, server_default="1"),  # optimistic lock for status changes
    Column("prompt_version", Text),
    Column("model_id", Text),
    _created(),
    _updated(),
    UniqueConstraint("job_id", "version"),
    Index("ix_emails_job_id", "job_id"),
)
# At most one sent email per job (job_id is UNIQUE).
sent_emails = Table(
    "sent_emails",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False, unique=True),
    Column("email_id", BigInteger, ForeignKey("emails.id"), nullable=False),
    Column("gmail_message_id", Text, nullable=False),
    Column("sent_at", DateTime(timezone=True), nullable=False),
    _created(),
)

# ---- Per-job chat memory and confirmation-only durable proposals ------------------------
chat_messages = Table(
    "chat_messages",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False),
    Column("role", Text, nullable=False),
    Column("text", Text, nullable=False),
    Column("tool_called", Text),
    Column("tier", Integer),
    Column("proposal_id", BigInteger, ForeignKey("proposals.id")),
    Column("version_created", Integer),
    Column("prompt_version", Text),
    Column("model_id", Text),
    _created(),
    Index("ix_chat_messages_job_id", "job_id"),
)

proposals = Table(
    "proposals",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False),
    Column("kind", Text, nullable=False),
    Column("target_id", BigInteger),
    Column("target_version", Integer),
    Column("before", JSONB, nullable=False),
    Column("after", JSONB, nullable=False),
    Column("status", Text, nullable=False, server_default="pending"),
    Column("callback_token", Text, nullable=False, unique=True),
    Column("version", Integer, nullable=False, server_default="1"),
    _created(),
    _updated(),
    Index("ix_proposals_job_id", "job_id"),
)

# ---- Generated, grounded interview preparation ------------------------------------------
prep_sets = Table(
    "prep_sets",
    metadata,
    _id(),
    _user(),
    Column("job_id", BigInteger, ForeignKey("jobs.id"), nullable=False, unique=True),
    Column("status", Text, nullable=False, server_default="queued"),
    Column("topic_map", JSONB, nullable=False, server_default=text("'[]'::jsonb")),
    Column("research", JSONB, nullable=False, server_default=text("'[]'::jsonb")),
    Column("dsa", JSONB, nullable=False, server_default=text("'[]'::jsonb")),
    Column("questions", JSONB, nullable=False, server_default=text("'[]'::jsonb")),
    Column("study_plan", JSONB, nullable=False, server_default=text("'{}'::jsonb")),
    # Prep v2 (decision 34): skill recap, resources for added skills and skills worth learning, and how the
    # pack was built (AI calls vs reused from storage). Questions stay in `questions`, each with its group.
    Column("pack", JSONB),
    Column("error", Text),
    Column("prompt_version", Text),
    Column("model_id", Text),
    Column("version", Integer, nullable=False, server_default="1"),
    _created(),
    _updated(),
)

# ---- Every paid jobs-API call, for the daily quota ----------------
api_usage = Table(
    "api_usage",
    metadata,
    _id(),
    _user(),
    Column("provider", Text, nullable=False),  # jsearch | serpapi
    Column("endpoint", Text, nullable=False),
    Column("run_id", BigInteger),
    _created(),
    Index("ix_api_usage_created_at", "created_at"),
)


# Daily card capacity held while a card is being built (renewed by the builder; expires after a crash).
card_reservations = Table(
    "card_reservations",
    metadata,
    Column("job_id", BigInteger, ForeignKey("jobs.id"), primary_key=True, autoincrement=False),
    _user(),
    Column("token", Text, nullable=False),
    Column("existing_card", Boolean, nullable=False),  # a rebuild of an existing card uses no new capacity
    Column("until", DateTime(timezone=True), nullable=False),
    _created(),
)
